/**
 * dsh-provider-usage/trend — 查询投影纯函数。
 *
 * 为什么独立成模块：趋势查询面（序列/堆叠/窗口摘要/目录投影）的计算与
 * TrendAggregator 的状态容器解耦——本模块全部函数以 days/dirDays/rows 显式传参，
 * 不接触 this（防「拆文件 = 共享 this」坏味道，layer-architecture.md §4 D-2）；
 * 主类保留状态容器与需要 this 的 IO/记账方法，查询方法变成薄壳委托。
 * 依赖方向无环：aggregate-query → types / charts / aggregate-rows；aggregator → 三者。
 *
 * 守恒边界（对账口径见 unit-trend-ledger.test.ts）：dirRows() 输出 = 目录桶
 * 快照 + 每日残差投影（归 TREND_UNIDENTIFIED）；无 dir 键的旧格式行只进聚合面不进
 * 目录面——目录维度守恒以「有 dir 事实」为界。小时面（buildHourRows）不做残差投影
 * （detail/counter 行必有 time，旧分片缺小时是物理缺失，报告侧 coveredDays 守卫降级）。
 */
import { dayKey, lastNDayKeys } from "../../shared/interface.ts";
import { emptyCell, diffToken } from "./aggregate-rows.ts";
import {
  sumToken,
  TREND_ROW_VERSION,
  TREND_UNIDENTIFIED,
  type TrendCell,
  type TrendDirRow,
  type TrendHourRow,
  type TrendMetric,
} from "../shared/interface.ts";
export type { TrendMetric } from "../shared/interface.ts";

/** 序列粒度。 */
export type TrendGranularity = "day" | "week" | "month";

/** 堆叠柱单段（一个 provider 或 provider+model 组合在一个时间桶内的取值）。 */
export interface TrendStackPart {
  provider: string;
  model: string | null;
  value: number | null;
}

/** 堆叠柱单根（一个时间桶）。 */
export interface TrendStackPoint {
  /** 桶键：day=YYYY-MM-DD / week=周首日 / month=YYYY-MM。 */
  key: string;
  parts: TrendStackPart[];
  /** 各段之和（null-aware；空桶 null）。 */
  total: number | null;
}

/** 窗口摘要（趋势页汇总卡数据源）。 */
export interface TrendWindowSummary {
  /** 当前窗口指标总量。 */
  total: number | null;
  calls: number;
  turns: number;
  toolCalls: number;
  /** 峰值桶键（total 最大的时间桶；无数据 null）。 */
  peakKey: string | null;
  /** 取值最大的适配器段。 */
  top: { provider: string; model: string | null; value: number } | null;
  /** 上一同等窗口指标总量（环比基准；无数据 null）。 */
  prevTotal: number | null;
  /** 上一窗口数据是否完整（起点早于数据起点 = false；false 时环比不可比）。 */
  prevComplete: boolean;
}

/** cell 的指标取值（#768 A波5：canonical 已下沉 server/shared/trend.ts，本文件 re-export 门面保留旧址兼容）。 */
export { metricValue } from "../shared/interface.ts";
import { metricValue } from "../shared/interface.ts";

/** 周一为起点的周首日 day key（本地时区；DST 安全——逐日回退不用毫秒减法）。 */
export function weekStartKey(t: number): string {
  const d = new Date(t);
  const dow = d.getDay(); // 0=周日
  const back = (dow + 6) % 7; // 距周一的天数
  d.setDate(d.getDate() - back);
  return dayKey(d.getTime());
}

/** 近 n 个周首日 key（升序，含当前周）。 */
export function lastNWeekKeys(n: number, now: number): string[] {
  const d = new Date(now);
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
  const keys: string[] = [];
  for (let i = 0; i < n; i += 1) {
    keys.unshift(dayKey(d.getTime()));
    d.setDate(d.getDate() - 7);
  }
  return keys;
}

/** 近 n 个月 key（YYYY-MM，升序，含当月；本地时区逐月回退）。 */
export function lastNMonthKeys(n: number, now: number): string[] {
  const d = new Date(now);
  const keys: string[] = [];
  for (let i = 0; i < n; i += 1) {
    keys.unshift(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`);
    d.setDate(1);
    d.setMonth(d.getMonth() - 1);
  }
  return keys;
}

/** 月 key 的日区间（本地日字典序；月末取该月最后一天，DST 安全）。 */
export function monthRange(key: string): { start: string; end: string } {
  const [y, m] = key.split("-").map(Number);
  const start = new Date(y, m - 1, 1);
  const end = new Date(y, m, 0); // 次月 0 日 = 本月末日
  return { start: dayKey(start.getTime()), end: dayKey(end.getTime()) };
}

/** 周首日 key 的日区间（7 天）。 */
export function weekRange(weekStart: string): { start: string; end: string } {
  const [y, m, d] = weekStart.split("-").map(Number);
  const start = new Date(y, m - 1, d);
  const endDate = new Date(y, m - 1, d + 6);
  return { start: dayKey(start.getTime()), end: dayKey(endDate.getTime()) };
}

/** 内存日桶的最早 day key（无数据返回 null；day key 字典序即时间序）。 */
function firstDayKeyOf(days: Map<string, unknown>): string | null {
  let first: string | null = null;
  for (const day of days.keys()) {
    if (first === null || day < first) first = day;
  }
  return first;
}

/** 粒度桶键序列（升序，含当前桶）。 */
function granKeysFor(n: number, gran: TrendGranularity, now: number): string[] {
  if (gran === "week") return lastNWeekKeys(n, now);
  if (gran === "month") return lastNMonthKeys(n, now);
  return lastNDayKeys(n, now);
}

/** 桶键 → 本地日区间。 */
function granRangeForKey(key: string, gran: TrendGranularity): { start: string; end: string } {
  if (gran === "week") return weekRange(key);
  if (gran === "month") return monthRange(key);
  return { start: key, end: key };
}

/** 上一窗口锚点（把 now 前移 n 桶，得到 prevKeys 与当前窗口不重叠的时点）。 */
function prevWindowAnchorFor(now: number, n: number, gran: TrendGranularity): number {
  const d = new Date(now);
  if (gran === "month") {
    d.setMonth(d.getMonth() - n);
    return d.getTime();
  }
  const days = gran === "week" ? n * 7 : n;
  d.setDate(d.getDate() - days);
  return d.getTime();
}

/** 日区间内的全部 (provider, model, cell)（升序日；provider 过滤可选）。 */
function rangeCellsOf(
  days: Map<string, Map<string, Map<string | null, TrendCell>>>,
  range: { start: string; end: string },
  provider?: string,
): Array<{ provider: string; model: string | null; cell: TrendCell }> {
  const out: Array<{ provider: string; model: string | null; cell: TrendCell }> = [];
  for (const [day, models] of days) {
    if (day < range.start || day > range.end) continue;
    for (const [p, cells] of models) {
      if (provider !== undefined && p !== provider) continue;
      for (const [m, cell] of cells) out.push({ provider: p, model: m, cell });
    }
  }
  return out;
}

/** 单日取值（provider 过滤可选；跨 model 求和；aggregator.seriesDays 委托用）。 */
export function dayValueOf(
  days: Map<string, Map<string, Map<string | null, TrendCell>>>,
  day: string,
  metric: TrendMetric,
  provider?: string,
): number | null {
  const models = days.get(day);
  if (models === undefined) return null;
  let acc: number | null = null;
  for (const [p, cells] of models) {
    if (provider !== undefined && p !== provider) continue;
    for (const cell of cells.values()) acc = sumToken(acc, metricValue(cell, metric));
  }
  return acc;
}

/** 日区间取值（[startDay, endDay] 闭区间，按本地日字典序比较；aggregator 序列方法委托用）。 */
export function rangeValueOf(
  days: Map<string, Map<string, Map<string | null, TrendCell>>>,
  range: { start: string; end: string },
  metric: TrendMetric,
  provider?: string,
): number | null {
  let acc: number | null = null;
  for (const [day, models] of days) {
    if (day < range.start || day > range.end) continue;
    for (const [p, cells] of models) {
      if (provider !== undefined && p !== provider) continue;
      for (const cell of cells.values()) acc = sumToken(acc, metricValue(cell, metric));
    }
  }
  return acc;
}

/**
 * 堆叠柱序列（/trend 路由数据源）：每时间桶按 provider（byModel 时细到
 * provider+model）拆段；providers 为图例并集（窗口内出现过的段）。
 */
export function buildStackedSeries(
  days: Map<string, Map<string, Map<string | null, TrendCell>>>,
  n: number,
  gran: TrendGranularity,
  metric: TrendMetric,
  provider: string | undefined,
  byModel: boolean,
  now: number,
): { series: TrendStackPoint[]; providers: Array<{ provider: string; model: string | null }> } {
  const keys = granKeysFor(n, gran, now);
  // 桶日区间一次算全（原实现对每桶在 days 日循环内重复调 granRange）
  const ranges = new Map(keys.map((k) => [k, granRangeForKey(k, gran)] as const));
  const series: TrendStackPoint[] = keys.map((key) => {
    const partsMap = new Map<string, TrendStackPart>();
    const range = ranges.get(key)!;
    for (const [day, models] of days) {
      if (day < range.start || day > range.end) continue;
      for (const [p, cells] of models) {
        if (provider !== undefined && p !== provider) continue;
        for (const [m, cell] of cells) {
          const id = byModel ? `${p}\u0000${m ?? ""}` : p;
          const v = metricValue(cell, metric);
          const cur = partsMap.get(id);
          if (cur !== undefined) cur.value = sumToken(cur.value, v);
          else partsMap.set(id, { provider: p, model: byModel ? m : null, value: v });
        }
      }
    }
    const parts = [...partsMap.values()];
    let total: number | null = null;
    for (const pt of parts) total = sumToken(total, pt.value);
    return { key, parts, total };
  });
  const legend = new Map<string, { provider: string; model: string | null }>();
  for (const point of series) {
    for (const pt of point.parts) {
      legend.set(byModel ? `${pt.provider}\u0000${pt.model ?? ""}` : pt.provider, {
        provider: pt.provider,
        model: byModel ? pt.model : null,
      });
    }
  }
  return { series, providers: [...legend.values()] };
}

/**
 * 堆叠柱序列（目录维度）。语义与 seriesStacked 同构：
 * 每时间桶按目录拆段；dirs 为图例并集（窗口内出现过的目录段，含未识别桶）。
 * dir 过滤可选（单目录形态——未识别桶键同为合法过滤值）。
 */
export function buildDirStackedSeries(
  rows: TrendDirRow[],
  n: number,
  gran: TrendGranularity,
  metric: TrendMetric,
  dir: string | undefined,
  now: number,
): { series: TrendStackPoint[]; dirs: Array<{ dir: string }> } {
  const keys = granKeysFor(n, gran, now);
  const ranges = new Map(keys.map((k) => [k, granRangeForKey(k, gran)] as const));
  // 行快照提出桶循环（原实现每桶 this.dirRows() 全量快照，O(桶×行)
  // 单请求重复；与 seriesStacked 同策略——range 一次算全 + 快照单次
  // 取用，桶循环内只做窗口过滤消费）。
  const series: TrendStackPoint[] = keys.map((key) => {
    const partsMap = new Map<string, TrendStackPart>();
    const range = ranges.get(key)!;
    for (const row of rows) {
      if (row.day < range.start || row.day > range.end) continue;
      if (dir !== undefined && row.dir !== dir) continue;
      const v = metricValue(row, metric);
      const cur = partsMap.get(row.dir);
      if (cur !== undefined) cur.value = sumToken(cur.value, v);
      else partsMap.set(row.dir, { provider: row.dir, model: null, value: v });
    }
    const parts = [...partsMap.values()];
    let total: number | null = null;
    for (const pt of parts) total = sumToken(total, pt.value);
    return { key, parts, total };
  });
  const legend = new Set<string>();
  for (const point of series) {
    for (const pt of point.parts) legend.add(pt.provider);
  }
  return { series, dirs: [...legend].sort().map((d) => ({ dir: d })) };
}

/**
 * 窗口摘要（当前 n 桶 + 上一同等窗口环比基准）。
 * @param stackSeries 可选传入路由已算好的堆叠序列（n/gran/metric/provider 必须与本
 *   调用一致）——复用峰值/Top 遍历，消除单请求双算；缺省时内部自算。
 */
export function buildWindowSummary(
  days: Map<string, Map<string, Map<string | null, TrendCell>>>,
  n: number,
  gran: TrendGranularity,
  metric: TrendMetric,
  provider: string | undefined,
  now: number,
  stackSeries?: TrendStackPoint[],
): TrendWindowSummary {
  const keys = granKeysFor(n, gran, now);
  const curRange = {
    start: granRangeForKey(keys[0], gran).start,
    end: granRangeForKey(keys[keys.length - 1], gran).end,
  };
  // 上一窗口：同长键序列整体前移 n 桶（day/week/month 各自步进语义）
  const prevKeys = granKeysFor(n, gran, prevWindowAnchorFor(now, n, gran));
  const prevRange = {
    start: granRangeForKey(prevKeys[0], gran).start,
    end: granRangeForKey(prevKeys[prevKeys.length - 1], gran).end,
  };
  let total: number | null = null;
  let calls = 0;
  let turns = 0;
  let toolCalls = 0;
  let peakKey: string | null = null;
  let peakVal = -1;
  let top: { provider: string; model: string | null; value: number } | null = null;
  // 复用路由已算的 stack 序列（消除单请求双算；缺省自算保持独立可用）
  const series =
    stackSeries ?? buildStackedSeries(days, n, gran, metric, provider, false, now).series;
  for (const point of series) {
    if (point.total !== null && point.total > peakVal) {
      peakVal = point.total;
      peakKey = point.key;
    }
    for (const pt of point.parts) {
      if (pt.value !== null && (top === null || pt.value > top.value)) {
        top = { provider: pt.provider, model: pt.model, value: pt.value };
      }
    }
  }
  for (const { cell } of rangeCellsOf(days, curRange, provider)) {
    total = sumToken(total, metricValue(cell, metric));
    calls += cell.calls;
    turns += cell.turns;
    toolCalls += cell.toolCalls;
  }
  return {
    total,
    calls,
    turns,
    toolCalls,
    peakKey,
    top,
    prevTotal: rangeValueOf(days, prevRange, metric, provider),
    // 上一窗口起点早于数据起点（内存最早日，即留存/起算边缘）→ 基准不完整，环比不可比
    prevComplete: prevRange.start >= (firstDayKeyOf(days) ?? "9999-12-31"),
  };
}

/**
 * 窗口摘要（目录维度）。curRange/prevRange 语义与
 * windowSummary 完全同构：当前窗口总量/调用数/峰值桶/目录 top 段 + 上一窗口环比。
 * prevComplete 语义对齐：prev 窗口起点早于**目录面数据起点**（dirRows 最早日；
 * 残差投影后该起点等于聚合面数据起点，故与 windowSummary 同值）→ 不可比。
 */
export function buildDirWindowSummary(
  rows: TrendDirRow[],
  n: number,
  gran: TrendGranularity,
  metric: TrendMetric,
  dir: string | undefined,
  now: number,
  dirSeries?: TrendStackPoint[],
): TrendWindowSummary {
  const keys = granKeysFor(n, gran, now);
  const curRange = {
    start: granRangeForKey(keys[0], gran).start,
    end: granRangeForKey(keys[keys.length - 1], gran).end,
  };
  const prevKeys = granKeysFor(n, gran, prevWindowAnchorFor(now, n, gran));
  const prevRange = {
    start: granRangeForKey(prevKeys[0], gran).start,
    end: granRangeForKey(prevKeys[prevKeys.length - 1], gran).end,
  };
  let total: number | null = null;
  let calls = 0;
  let turns = 0;
  let toolCalls = 0;
  let prevTotal: number | null = null;
  let peakKey: string | null = null;
  let peakVal = -1;
  let top: { provider: string; model: string | null; value: number } | null = null;
  const series = dirSeries ?? buildDirStackedSeries(rows, n, gran, metric, dir, now).series;
  for (const point of series) {
    if (point.total !== null && point.total > peakVal) {
      peakVal = point.total;
      peakKey = point.key;
    }
    for (const pt of point.parts) {
      if (pt.value !== null && (top === null || pt.value > top.value)) {
        top = { provider: pt.provider, model: pt.model, value: pt.value };
      }
    }
  }
  let firstDirDay: string | null = null;
  // 单遍遍历（原实现 3 次全量遍历 rows——最早日 + 当前窗口 + 上一
  // 窗口各一遍；窗口区间互斥，同遍累加语义不变）。
  for (const row of rows) {
    if (firstDirDay === null || row.day < firstDirDay) firstDirDay = row.day;
    const inDir = dir === undefined || row.dir === dir;
    if (inDir && row.day >= curRange.start && row.day <= curRange.end) {
      total = sumToken(total, metricValue(row, metric));
      calls += row.calls;
      turns += row.turns;
      toolCalls += row.toolCalls;
    }
    if (inDir && row.day >= prevRange.start && row.day <= prevRange.end) {
      prevTotal = sumToken(prevTotal, metricValue(row, metric));
    }
  }
  return {
    total,
    calls,
    turns,
    toolCalls,
    peakKey,
    top,
    prevTotal,
    // 与 windowSummary.prevComplete 同口径：prev 窗口起点早于目录数据起点 → 环比不可比
    prevComplete: prevRange.start >= (firstDirDay ?? "9999-12-31"),
  };
}

/**
 * 目录窗口总量表（目录范围口径影响 + 目录分布数据源）：
 * 给定日区间内按目录聚合 calls 与 metric 总量（calls 降序）。
 */
export function buildDirTotals(
  rows: TrendDirRow[],
  startDay: string,
  endDay: string,
  metric: TrendMetric = "total",
): Array<{ dir: string; calls: number; total: number | null }> {
  const byDir = new Map<string, { dir: string; calls: number; total: number | null }>();
  for (const row of rows) {
    if (row.day < startDay || row.day > endDay) continue;
    let cur = byDir.get(row.dir);
    if (cur === undefined) {
      cur = { dir: row.dir, calls: 0, total: null };
      byDir.set(row.dir, cur);
    }
    cur.calls += row.calls;
    cur.total = sumToken(cur.total, metricValue(row, metric));
  }
  return [...byDir.values()].sort((a, b) => b.calls - a.calls);
}

/**
 * 全量目录日桶快照（day 升序；报告快照与统计目录分布数据源）。
 *
 * 权威口径：dirDays 单源快照——apply 平行累加 + rebuild 双分支读回
 * 已覆盖全部 dir 事实，不再折算 pending 行（旧折算侧与 dirDays 并存时双算：
 * 同事实重建 → 2×；互补事实 → 按键去重丢数；实测同日重启续 apply input 17 → 7）。
 *
 * 残差投影（取代「重建时补造」）：目录面 = dirDays 快照 + 每日残差。
 * 残差(day) = 该日聚合面（cells，全量事实）− 该日 dirDays 合计（有目录归属的事实），
 * 非零则投影为一条 `{day, dir: TREND_UNIDENTIFIED}` 行——语义即「该日无目录信息的
 * 数据」。这样两个查询面的日总量恒等（目录面 = 聚合面），且**不会双算**：
 *
 * - 旧分片（无 kind:"dir" 行的 agg 行）：cells 有值、dirDays 空 → 残差
 *   = 全量 → 历史柱恢复且不丢数（此前 dir 面历史全 null，实测差 20 倍）；
 * - 新分片（agg + dir 并存，同一批事实的两个投影）：cells 含 agg 行、dirDays 含 dir 行
 *   → 残差 ≈ 0（同一事实相减相消）→ 不补造、不双算；故**禁止**在 rebuild 里对
 *   agg 行补造未识别桶（会与 dir 行双算，反例：9-05 的 rjk2 calls=22 会变 44）；
 * - 混版日（升级当天：旧 agg 行 + 新 dir 行并存）：残差 = 旧 agg 部分 → 归未识别，
 *   新 dir 行照常分目录，既不丢升级前的历史、也不把新数据算进未识别；
 * - 当日未压实：apply 对 cells 与 dirDays 平行累加 → 残差 ≈ 0。
 *
 * 不变量：∀day 目录面日合计 == 聚合面日合计（残差为负即数据不一致——目录行多于聚合行，
 * 属双算/漂移征兆，投影按 0 处理并保持数值可解释，不产生负柱）。
 * 残留边界（文档化口径）：残差只有日粒度（dirDays 无 provider 维度），故「无目录信息的
 * 数据」只能整体归未识别桶，无法细分到 provider/model——目录面与 provider 面本互斥
 * （见 routes/ui.ts 的 dir/byDir 分流），无消费方需要该交叉维度。
 */
export function buildDirRows(
  days: Map<string, Map<string, Map<string | null, TrendCell>>>,
  dirDays: Map<string, Map<string, TrendCell>>,
): TrendDirRow[] {
  // 输出容器按 (day, dir) 唯一：dirDays 桶与残差行可能撞同一键（混版日已有
  // (unidentified) 桶时），撞键即合并数值，绝不产出重复键行（公开面契约）。
  // 保持 dirDays 分支的插入序（day 升序、day 内 dir 键插入序）——下游 dirTotals
  // 用稳定排序，行序变化会改变「候选 calls 降序」的并列顺序。
  const out: TrendDirRow[] = [];
  const byKey = new Map<string, TrendDirRow>();
  const put = (row: TrendDirRow): void => {
    const key = `${row.day}\u0000${row.dir}`;
    const cur = byKey.get(key);
    if (cur === undefined) {
      byKey.set(key, row);
      out.push(row);
      return;
    }
    cur.input = sumToken(cur.input, row.input);
    cur.output = sumToken(cur.output, row.output);
    cur.cacheRead = sumToken(cur.cacheRead, row.cacheRead);
    cur.cacheWrite = sumToken(cur.cacheWrite, row.cacheWrite);
    cur.calls += row.calls;
    cur.turns += row.turns;
    cur.toolCalls += row.toolCalls;
  };
  for (const day of [...dirDays.keys()].sort()) {
    for (const [dir, cell] of dirDays.get(day)!) {
      put({
        v: TREND_ROW_VERSION,
        kind: "dir",
        day,
        dir,
        input: cell.input,
        output: cell.output,
        cacheRead: cell.cacheRead,
        cacheWrite: cell.cacheWrite,
        calls: cell.calls,
        turns: cell.turns,
        toolCalls: cell.toolCalls,
      });
    }
  }
  // 每日残差：聚合面（cells）− 目录面（dirDays）。cells 的键是 day → provider →
  // model，逐层求和得该日全量；dirDays 的键是 day → dir，同法求该日目录合计。
  const aggByDay = new Map<string, TrendCell>();
  for (const [day, providers] of days) {
    let cell = aggByDay.get(day);
    if (cell === undefined) {
      cell = emptyCell();
      aggByDay.set(day, cell);
    }
    for (const models of providers.values()) {
      for (const c of models.values()) {
        cell.input = sumToken(cell.input, c.input);
        cell.output = sumToken(cell.output, c.output);
        cell.cacheRead = sumToken(cell.cacheRead, c.cacheRead);
        cell.cacheWrite = sumToken(cell.cacheWrite, c.cacheWrite);
        cell.calls += c.calls;
        cell.turns += c.turns;
        cell.toolCalls += c.toolCalls;
      }
    }
  }
  // 残差按 day 升序处理（cells 的 Map 键序是插入序，时钟回拨会让旧日新桶排在末尾；
  // 公开方法契约声明 day 升序，故此处显式排序，不依赖插入序）。
  for (const day of [...aggByDay.keys()].sort()) {
    const cell = aggByDay.get(day)!;
    let dirInput: number | null = null;
    let dirOutput: number | null = null;
    let dirCacheRead: number | null = null;
    let dirCacheWrite: number | null = null;
    let dirCalls = 0;
    let dirTurns = 0;
    let dirToolCalls = 0;
    const dirs = dirDays.get(day);
    if (dirs !== undefined) {
      for (const c of dirs.values()) {
        dirInput = sumToken(dirInput, c.input);
        dirOutput = sumToken(dirOutput, c.output);
        dirCacheRead = sumToken(dirCacheRead, c.cacheRead);
        dirCacheWrite = sumToken(dirCacheWrite, c.cacheWrite);
        dirCalls += c.calls;
        dirTurns += c.turns;
        dirToolCalls += c.toolCalls;
      }
    }
    // 残差 = 聚合面 − 目录面（null-aware：双方皆 null → 0/无残差；单侧 null 按 0 计）
    const input = diffToken(cell.input, dirInput);
    const output = diffToken(cell.output, dirOutput);
    const cacheRead = diffToken(cell.cacheRead, dirCacheRead);
    const cacheWrite = diffToken(cell.cacheWrite, dirCacheWrite);
    const calls = cell.calls - dirCalls;
    const turns = cell.turns - dirTurns;
    const toolCalls = cell.toolCalls - dirToolCalls;
    // 全部为 0/空 = 该日目录面已覆盖全量（新分片常态）→ 不补造行。
    // 负残差（目录面多于聚合面）同样走此分支（不产行）：属数据不一致征兆
    // （例如明细目录误落 dir 行——已由 readDetailShard 白名单阻断），此时目录面
    // 日合计会大于聚合面，README「总量守恒」节已注明该边界不保证恒等。
    const hasResidual =
      calls > 0 ||
      turns > 0 ||
      toolCalls > 0 ||
      (input ?? 0) > 0 ||
      (output ?? 0) > 0 ||
      (cacheRead ?? 0) > 0 ||
      (cacheWrite ?? 0) > 0;
    if (!hasResidual) continue;
    // 同键（该日已有 (unidentified) 桶，混版日常态）由 put 合并到既有行，
    // 保证 (day, dir) 键唯一；负值按 0 处理（不产生负柱）。
    put({
      v: TREND_ROW_VERSION,
      kind: "dir",
      day,
      dir: TREND_UNIDENTIFIED,
      input: input !== null && input > 0 ? input : null,
      output: output !== null && output > 0 ? output : null,
      cacheRead: cacheRead !== null && cacheRead > 0 ? cacheRead : null,
      cacheWrite: cacheWrite !== null && cacheWrite > 0 ? cacheWrite : null,
      calls: calls > 0 ? calls : 0,
      turns: turns > 0 ? turns : 0,
      toolCalls: toolCalls > 0 ? toolCalls : 0,
    });
  }
  // 顺序契约：dirDays 分支按 day 升序、day 内按 dir 键插入序输出；残差行按 day
  // 升序追加在尾段（已显式排序，不依赖 cells 插入序）。**不做全局 sort(day, dir)**：
  // 它会把残差行的未识别键排到该日首位（"(" 字典序最前），改变 dirTotals 的插入序；
  // dirTotals 用稳定排序（同 calls 保持插入序），下游「候选 calls 降序」并列顺序
  // 因此会被打破。
  return out;
}

/**
 * 全量小时日桶快照（day 升序、hour 升序；报告快照 byHour/byPeriod/peakHour/
 * coveredDays 数据源）。
 * 权威口径（对齐 dirRows 单源约定）：hourDays 单源快照——apply 平行累加 + rebuild
 * 双分支读回已覆盖全部 hour 事实，不折算 pending（防双算）；**不做残差投影**
 * （detail/counter 必有 time、无缺键事实；旧分片缺 hour 行是物理缺失，报告侧
 * coveredDays 守卫负责降级，不投影补造伪事实）。
 */
export function buildHourRows(hourDays: Map<string, Map<number, TrendCell>>): TrendHourRow[] {
  const out: TrendHourRow[] = [];
  for (const day of [...hourDays.keys()].sort()) {
    const byHour = hourDays.get(day)!;
    for (const hour of [...byHour.keys()].sort((a, b) => a - b)) {
      const cell = byHour.get(hour)!;
      out.push({
        v: TREND_ROW_VERSION,
        kind: "hour",
        day,
        hour,
        input: cell.input,
        output: cell.output,
        cacheRead: cell.cacheRead,
        cacheWrite: cell.cacheWrite,
        calls: cell.calls,
        turns: cell.turns,
        toolCalls: cell.toolCalls,
      });
    }
  }
  return out;
}

/**
 * dsh-provider-usage/trend — 压实转换纯函数。
 *
 * 为什么独立成模块：TrendAggregator 原 1300+ 行混合「状态容器 +
 * IO 方法」与纯函数转换；拆分后本模块只含行形态转换——明细/计数行并入聚合/目录/小时行、
 * 汇总行合并（merge*）、null-aware token 差（sub/diffToken）与空行构造。全部参数显式传入、
 * 不接触 this：防「拆文件 = 共享 this」坏味道（layer-architecture.md §4 D-2 前置约定，
 * 需状态者一律留在主类）。本模块无 import 环（只依赖 types.ts）。
 *
 * null 语义（与聚合面一致）：token 求和 null-aware（sumToken）——缺失维度不参与求和；
 * 0 是有效数字参与求和（校正把数字改 null 时 cell 残留 0 属既有增量语义，见 sub 注释）。
 */
import {
  sumToken,
  TREND_ROW_VERSION,
  type TrendAggRow,
  type TrendCell,
  type TrendDetailRow,
  type TrendDirRow,
  type TrendHourRow,
} from "../shared/interface.ts";

/** token 差（cell 回退用）：有值→null 时增量为 -old（cell 同步扣减，保证内存聚合
 *  与校正后的落盘明细一致）；双方皆 null 增量 0（null-aware 无变化）。 */
export function sub(oldV: number | null, newV: number | null): number | null {
  if (newV === null) return oldV === null ? null : -oldV;
  if (oldV === null) return newV;
  return newV - oldV;
}

/**
 * 残差投影的 token 差：聚合面 − 目录面，null-aware。
 * 双方皆 null → null（无该维度事实）；单侧 null 按 0 参与（另一侧有值即有残差）；
 * 负值保留给调用方判定（调用方按 0 处理并依赖「日总量恒等」断言暴露不一致）。
 */
export function diffToken(aggV: number | null, dirV: number | null): number | null {
  if (aggV === null && dirV === null) return null;
  return (aggV ?? 0) - (dirV ?? 0);
}

/** 单元格空壳（桶缺位时补建）。 */
export function emptyCell(): TrendCell {
  return {
    input: null,
    output: null,
    cacheRead: null,
    cacheWrite: null,
    calls: 0,
    turns: 0,
    toolCalls: 0,
  };
}

/** 空聚合行（压实折算起点；字段与 mergeCell 消费的 agg 行同构）。 */
export function emptyAggRow(day: string, provider: string, model: string | null): TrendAggRow {
  return {
    v: TREND_ROW_VERSION,
    kind: "agg",
    day,
    provider,
    model,
    input: null,
    output: null,
    cacheRead: null,
    cacheWrite: null,
    calls: 0,
    turns: 0,
    toolCalls: 0,
  };
}

/** 空目录汇总行（与 agg 行十数值字段同构，仅键换成 dir）。 */
export function emptyDirRow(day: string, dir: string): TrendDirRow {
  return {
    v: TREND_ROW_VERSION,
    kind: "dir",
    day,
    dir,
    input: null,
    output: null,
    cacheRead: null,
    cacheWrite: null,
    calls: 0,
    turns: 0,
    toolCalls: 0,
  };
}

/** 空小时汇总行（与 agg/dir 行同构，键换成 hour；「落盘即定型」的产出起点）。 */
export function emptyHourRow(day: string, hour: number): TrendHourRow {
  return {
    v: TREND_ROW_VERSION,
    kind: "hour",
    day,
    hour,
    input: null,
    output: null,
    cacheRead: null,
    cacheWrite: null,
    calls: 0,
    turns: 0,
    toolCalls: 0,
  };
}

/** 明细行并入聚合/目录/小时汇总行（三者字段同构，同函数复用；null-aware 求和）。 */
export function addDetailTo(
  agg: TrendAggRow | TrendDirRow | TrendHourRow,
  row: TrendDetailRow,
): void {
  agg.calls += 1;
  agg.input = sumToken(agg.input, row.input);
  agg.output = sumToken(agg.output, row.output);
  agg.cacheRead = sumToken(agg.cacheRead, row.cacheRead);
  agg.cacheWrite = sumToken(agg.cacheWrite, row.cacheWrite);
}

/** 计数行并入聚合/目录/小时汇总行（同上，同函数复用）。 */
export function addCounterTo(
  agg: TrendAggRow | TrendDirRow | TrendHourRow,
  turns: number,
  toolCalls: number,
): void {
  agg.turns += turns;
  agg.toolCalls += toolCalls;
}

/** 聚合行并入 cell（重建用；null-aware。agg/dir/hour 汇总行十数值字段同构，同函数复用）。 */
export function mergeCell(cell: TrendCell, row: TrendAggRow | TrendDirRow | TrendHourRow): void {
  cell.calls += row.calls;
  cell.turns += row.turns;
  cell.toolCalls += row.toolCalls;
  cell.input = sumToken(cell.input, row.input);
  cell.output = sumToken(cell.output, row.output);
  cell.cacheRead = sumToken(cell.cacheRead, row.cacheRead);
  cell.cacheWrite = sumToken(cell.cacheWrite, row.cacheWrite);
}

/**
 * 聚合行合并（flush 压实写盘前与既有聚合分片合并——迟到旧日行场景防覆盖丢数；
 * null-aware 求和，同 (provider, model) 键累加）。
 */
export function mergeAggRows(base: TrendAggRow[], add: TrendAggRow[]): TrendAggRow[] {
  const byKey = new Map<string, TrendAggRow>();
  for (const r of [...base, ...add]) {
    const key = `${r.provider}\u0000${r.model ?? ""}`;
    const cur = byKey.get(key);
    if (cur === undefined) {
      byKey.set(key, { ...r });
      continue;
    }
    cur.calls += r.calls;
    cur.turns += r.turns;
    cur.toolCalls += r.toolCalls;
    cur.input = sumToken(cur.input, r.input);
    cur.output = sumToken(cur.output, r.output);
    cur.cacheRead = sumToken(cur.cacheRead, r.cacheRead);
    cur.cacheWrite = sumToken(cur.cacheWrite, r.cacheWrite);
  }
  return [...byKey.values()];
}

/**
 * dir 汇总行合并（flush 压实写盘前与既有聚合分片内的 dir 行合并——
 * 迟到旧日行场景防覆盖丢数；十数值字段与 mergeAggRows 完全同构，null-aware
 * 求和，同 dir 键累加。输出保持输入相对顺序：base 在前（dir 行位于分片尾段））。
 */
export function mergeDirRows(base: TrendDirRow[], add: TrendDirRow[]): TrendDirRow[] {
  const byKey = new Map<string, TrendDirRow>();
  for (const r of [...base, ...add]) {
    const cur = byKey.get(r.dir);
    if (cur === undefined) {
      byKey.set(r.dir, { ...r });
      continue;
    }
    cur.calls += r.calls;
    cur.turns += r.turns;
    cur.toolCalls += r.toolCalls;
    cur.input = sumToken(cur.input, r.input);
    cur.output = sumToken(cur.output, r.output);
    cur.cacheRead = sumToken(cur.cacheRead, r.cacheRead);
    cur.cacheWrite = sumToken(cur.cacheWrite, r.cacheWrite);
  }
  return [...byKey.values()];
}

/**
 * hour 汇总行合并（flush 压实写盘前与既有聚合分片内的 hour 行合并——
 * 迟到旧日行二次压实防丢防重；与 mergeDirRows 完全同构，同 hour 键累加，
 * 输出保持输入相对顺序：base 在前（hour 行位于分片尾段））。
 */
export function mergeHourRows(base: TrendHourRow[], add: TrendHourRow[]): TrendHourRow[] {
  const byKey = new Map<number, TrendHourRow>();
  for (const r of [...base, ...add]) {
    const cur = byKey.get(r.hour);
    if (cur === undefined) {
      byKey.set(r.hour, { ...r });
      continue;
    }
    cur.calls += r.calls;
    cur.turns += r.turns;
    cur.toolCalls += r.toolCalls;
    cur.input = sumToken(cur.input, r.input);
    cur.output = sumToken(cur.output, r.output);
    cur.cacheRead = sumToken(cur.cacheRead, r.cacheRead);
    cur.cacheWrite = sumToken(cur.cacheWrite, r.cacheWrite);
  }
  return [...byKey.values()];
}

/**
 * dsh-provider-usage/trend — 内存聚合主类。
 *
 * 两级聚合（方案定稿）：
 * - cells：day×provider(×model) 桶，apply 时实时累加（含未压实的历史日）；
 * - pending：当日 per-step 明细/计数行（未压实窗口），支撑今日按小时/按会话细分
 *   与日切压实的落盘素材；日切时压实为 day×provider(×model) 聚合行并丢弃明细。
 *
 * 小时维度（hourDays）：day→hour(0-23)→cell 桶，与 dirDays 同模式——apply
 * 平行累加（hourOfDay 现算自事件 time）、rebuild 双分支读回（hour 行直接入桶 +
 * 当日明细/计数行折算入桶）、retokenCell 第三面修正、pruneDays 联动删除；
 * 不设残差投影（detail/counter 行必有 time、无缺键事实；旧分片缺小时是物理缺失，
 * 投影救不回且会造伪事实）——「小时面=聚合面」守恒由 rollupSnapshot 同源折算
 * （同一事实的第三个投影）+ 覆盖度守卫 + 测试断言共同保证。
 *
 * 双算防线：明细/计数行在 apply 时已进 cells，压实只做「落盘形态转换」
 * （明细行 → 聚合行），绝不再次累加 cells；重启重建时聚合行与当日明细行
 * 二选一来源（agg 分片存在即权威，见 store 约定），同样不双算。
 *
 * null 语义：桶内 token 求和 null-aware（无任何有效数字保持 null）；
 * 调用/轮次/工具计数独立累加，与 token 有无无关。
 *
 * 本文件只保留状态容器（days/dirDays/hourDays/pending）与需要访问状态的方法——
 * apply/rebuild/rollupSnapshot/consume/prune 等 IO 与状态操作；
 * 压实转换纯函数迁至 aggregate-rows.ts，查询投影纯函数迁至 aggregate-query.ts
 * （二者均参数显式传入、不接触 this，防「拆文件 = 共享 this」坏味道；公开导出面
 * 经本文件尾部 re-export 保持可达，目录化后消费方走 aggregate/interface.ts）。
 */
import { dayKey, lastNDayKeys } from "../../shared/interface.ts";
import {
  sumToken,
  hourOfDay,
  TREND_ROW_VERSION,
  type TrendAggRow,
  type TrendCell,
  type TrendCounterRow,
  type TrendDetailRow,
  type TrendDirRow,
  type TrendHourRow,
  type TrendTokens,
} from "../shared/interface.ts";
import type {
  TrendCallRecord,
  TrendCorrectRecord,
  TrendCounterRecord,
  TrendEmit,
} from "../collect/interface.ts";
import {
  emptyCell,
  emptyAggRow,
  emptyDirRow,
  emptyHourRow,
  addDetailTo,
  addCounterTo,
  mergeCell,
  sub,
} from "./aggregate-rows.ts";
import {
  lastNWeekKeys,
  lastNMonthKeys,
  monthRange,
  weekRange,
  dayValueOf,
  rangeValueOf,
  buildDirRows,
  buildHourRows,
  buildStackedSeries,
  buildDirStackedSeries,
  buildWindowSummary,
  buildDirWindowSummary,
  buildDirTotals,
  type TrendGranularity,
  type TrendMetric,
  type TrendStackPoint,
  type TrendWindowSummary,
} from "./aggregate-query.ts";

/** 未压实行（内存持有；flush 时持久化，压实后移除）。 */
export interface PendingEntry {
  row: TrendDetailRow | TrendCounterRow;
  /** 已 append 到当日分片（重启重建的行也为 true，防二次落盘）。 */
  persisted: boolean;
}

export class TrendAggregator {
  /** day → provider → model(null 允许) → cell。 */
  private days = new Map<string, Map<string, Map<string | null, TrendCell>>>();
  /**
   * day → dir → cell（目录维度日汇总内存态）。
   * 生命周期与 days 同步：apply 实时累加 → rebuild 的
   * dir 汇总行与明细/计数行（有 dir 键者）双向读回 → 压实消费不删（与
   * cells 同策略，跨天后目录查询面历史柱不失——dirRows 纯内存无分片回读）
   * → prune 同步收缩（pruneDays 联动删除）。
   * 权威口径：dirDays 是目录维度的唯一事实源——apply 平行累加 +
   * rebuild 双分支读回已覆盖全部 dir 事实，dirRows() 只做快照不再折算 pending
   * （单源无重无漏：同事实并存时折算会 2×，互补事实并存时按键去重会丢）。
   */
  private dirDays = new Map<string, Map<string, TrendCell>>();
  /**
   * day → hour(0-23) → cell（小时维度日汇总内存态）。
   * 生命周期与 days/dirDays 同步：apply 实时累加 → rebuild
   * 双分支读回（hour 行 mergeCell + 当日明细/计数行折算）→ 压实消费不删（与
   * cells/dirDays 同策略，跨天后小时面历史不丢——hourRows 纯内存无分片回读）
   * → prune 同步收缩（pruneDays 联动删除）。
   * 权威口径：hourDays 是小时维度的唯一事实源——apply 平行累加 + rebuild 双分支
   * 读回已覆盖全部 hour 事实，hourRows() 只做快照（同 dirRows 单源无重无漏）。
   * 不做残差投影（与 dir 本质差异见文件头注释）；「小时面=聚合面」守恒由
   * rollupSnapshot 同源折算 + 报告侧 coveredDays 守卫 + 测试断言共同保证。
   */
  private hourDays = new Map<string, Map<number, TrendCell>>();
  /** 未压实明细/计数行（跨日可能：时钟回拨把旧日事件记进对应日分片）。 */
  private pending: PendingEntry[] = [];

  // ---------------------------------------------------------------- 实时记账

  /** 应用一条定稿记录（collector emit 出口）。 */
  apply(e: TrendEmit): void {
    switch (e.type) {
      case "call":
        this.applyCall(e.record);
        return;
      case "correct":
        this.applyCorrect(e.record);
        return;
      case "counter":
        this.applyCounter(e.record);
        return;
    }
  }

  /** call 量累加进 cell（applyCall / rebuild 明细行共用，cells 与 dirCells 同构复用）。 */
  private addCall(cell: TrendCell, tokens: TrendTokens | null): void {
    cell.calls += 1;
    if (tokens !== null) {
      cell.input = sumToken(cell.input, tokens.input);
      cell.output = sumToken(cell.output, tokens.output);
      cell.cacheRead = sumToken(cell.cacheRead, tokens.cacheRead);
      cell.cacheWrite = sumToken(cell.cacheWrite, tokens.cacheWrite);
    }
  }

  private applyCall(r: TrendCallRecord): void {
    const day = dayKey(r.time);
    this.addCall(this.cellOf(day, r.provider, r.model), r.tokens);
    // A4(f)补dir：目录维度为加性可选键——缺键只进 agg 面，不建 undefined 键桶
    //（与 rebuild/rollupSnapshot/retokenCell 的 `dir !== undefined` 守卫同口径）。
    if (r.dir !== undefined) this.addCall(this.dirCellOf(day, r.dir), r.tokens); // 目录维度平行累加（同 record 不二次 emit）
    this.addCall(this.hourCellOf(day, hourOfDay(r.time)), r.tokens); // 小时维度平行累加（hourOfDay 与 dayKey 同源，日界一致）
    const row: TrendDetailRow = {
      v: TREND_ROW_VERSION,
      kind: "detail",
      time: r.time,
      day,
      session: r.session,
      turn: r.turn,
      step: r.step,
      retry: r.retry,
      provider: r.provider,
      model: r.model,
      dir: r.dir, // 目录归属落盘（collector.dirOf 已保证 sanitize 后 basename 或未识别桶，不重复净化）
      input: r.tokens?.input ?? null,
      output: r.tokens?.output ?? null,
      cacheRead: r.tokens?.cacheRead ?? null,
      cacheWrite: r.tokens?.cacheWrite ?? null,
      calls: 1,
      ...(r.interrupted === true ? { interrupted: true as const } : {}),
    };
    this.pending.push({ row, persisted: false });
  }

  /** 校正：覆盖未压实窗口内同 fold 键最后一条明细的 token（已压实的不追溯）。 */
  private applyCorrect(r: TrendCorrectRecord): void {
    for (let i = this.pending.length - 1; i >= 0; i -= 1) {
      const { row } = this.pending[i];
      if (
        row.kind === "detail" &&
        row.session === r.session &&
        row.turn === r.turn &&
        row.step === r.step &&
        row.retry === r.retry
      ) {
        this.retokenCell(row, r.tokens); // 先回退旧值再累加新值（cell 增量一致）
        row.input = r.tokens.input;
        row.output = r.tokens.output;
        row.cacheRead = r.tokens.cacheRead;
        row.cacheWrite = r.tokens.cacheWrite;
        return;
      }
    }
    /* 未找到（已压实/重启后迟到）：校正窗口已关闭，按口径不追溯 */
  }

  /**
   * 明细行 token 变更的 cell 增量修正。
   * cells 与 dirDays 双面同步修正——dirDays 单源化后（dirRows 只读
   * 快照、不再折算 pending），applyCorrect 的行值变更必须同步回目录桶，否则
   * 目录查询面与 cells/落盘行漂移（修正前折算侧取 pending 行新值掩盖了漂移，
   * 单源化后漂移会固化）。两桶增量一致（同 sub 差值），null-aware。
   */
  private retokenCell(row: TrendDetailRow, next: TrendTokens): void {
    const deltas: TrendTokens = {
      input: sub(row.input, next.input),
      output: sub(row.output, next.output),
      cacheRead: sub(row.cacheRead, next.cacheRead),
      cacheWrite: sub(row.cacheWrite, next.cacheWrite),
    };
    const cell = this.cellOf(row.day, row.provider, row.model);
    cell.input = sumToken(cell.input, deltas.input);
    cell.output = sumToken(cell.output, deltas.output);
    cell.cacheRead = sumToken(cell.cacheRead, deltas.cacheRead);
    cell.cacheWrite = sumToken(cell.cacheWrite, deltas.cacheWrite);
    if (row.dir !== undefined) {
      const dirCell = this.dirCellOf(row.day, row.dir);
      dirCell.input = sumToken(dirCell.input, deltas.input);
      dirCell.output = sumToken(dirCell.output, deltas.output);
      dirCell.cacheRead = sumToken(dirCell.cacheRead, deltas.cacheRead);
      dirCell.cacheWrite = sumToken(dirCell.cacheWrite, deltas.cacheWrite);
    }
    // 小时面第三面修正——applyCorrect 的行值变更必须同步回小时桶（dirDays
    // 单源化后折算侧不再兜底；hourOfDay 与 apply 时同源现算，桶键一致）。
    const hourCell = this.hourCellOf(row.day, hourOfDay(row.time));
    hourCell.input = sumToken(hourCell.input, deltas.input);
    hourCell.output = sumToken(hourCell.output, deltas.output);
    hourCell.cacheRead = sumToken(hourCell.cacheRead, deltas.cacheRead);
    hourCell.cacheWrite = sumToken(hourCell.cacheWrite, deltas.cacheWrite);
  }

  /** counter 量累加进 cell（applyCounter / rebuild 计数行共用）。 */
  private addCounter(cell: TrendCell, turns: number, toolCalls: number): void {
    cell.turns += turns;
    cell.toolCalls += toolCalls;
  }

  private applyCounter(r: TrendCounterRecord): void {
    const day = dayKey(r.time);
    this.addCounter(this.cellOf(day, r.provider, r.model), r.turns, r.toolCalls);
    // A4(f)补dir：同上（加性可选键，缺键跳过目录桶；与 call 路径对称）。
    if (r.dir !== undefined) this.addCounter(this.dirCellOf(day, r.dir), r.turns, r.toolCalls); // 目录维度平行累加
    this.addCounter(this.hourCellOf(day, hourOfDay(r.time)), r.turns, r.toolCalls); // 小时维度平行累加
    const row: TrendCounterRow = {
      v: TREND_ROW_VERSION,
      kind: "counter",
      time: r.time,
      day,
      session: r.session,
      provider: r.provider,
      model: r.model,
      dir: r.dir, // 目录归属落盘（同 detail 行约定）
      turns: r.turns,
      toolCalls: r.toolCalls,
    };
    this.pending.push({ row, persisted: false });
  }

  // ---------------------------------------------------------------- 重建（重启载入）

  /**
   * 重启重建：重放分片行进内存（cells 更新 + 未压实行登记）。
   * @param rows 校验过的分片行（agg 权威行 + 当日明细/计数行）
   * @param persistedRows 这些行是否已落盘（agg 行无意义；明细/计数行来自分片 = true）
   */
  rebuild(
    rows: Array<TrendAggRow | TrendDetailRow | TrendCounterRow | TrendDirRow | TrendHourRow>,
    persistedRows: boolean,
  ): void {
    for (const row of rows) {
      if (row.kind === "agg") {
        const cell = this.cellOf(row.day, row.provider, row.model);
        mergeCell(cell, row);
        continue;
      }
      // dir 汇总行重建 → 只进目录维度桶（cells 累加只发生在事件路径与
      // detail/counter 行重建，防双重计数）
      if (row.kind === "dir") {
        mergeCell(this.dirCellOf(row.day, row.dir), row);
        continue;
      }
      // hour 汇总行重建 → 只进小时维度桶（同 dir 行：防双重计数、不进 pending）
      if (row.kind === "hour") {
        mergeCell(this.hourCellOf(row.day, row.hour), row);
        continue;
      }
      if (row.kind === "detail") {
        this.addCall(this.cellOf(row.day, row.provider, row.model), {
          input: row.input,
          output: row.output,
          cacheRead: row.cacheRead,
          cacheWrite: row.cacheWrite,
        });
        // 明细行 rebuild 双面入账（与 cells 同策略）——dirDays 是目录
        // 维度唯一事实源（dirRows 纯快照不折算 pending），重建明细行的 dir 事实
        // 必须在此落桶，否则重启后目录查询面丢「分片明细形态存在、dirDays 缺失」
        // 的事实（自愈/当日重建两条路径同病；实测 Day0 input 10 → 7）。
        if (row.dir !== undefined) {
          this.addCall(this.dirCellOf(row.day, row.dir), {
            input: row.input,
            output: row.output,
            cacheRead: row.cacheRead,
            cacheWrite: row.cacheWrite,
          });
        }
        // 明细行 rebuild 第三面入账——hourDays 是小时维度唯一事实源，
        // 重建明细行的 hour 事实必须在此落桶（hourOfDay 与 apply 同源现算；
        // 已落盘 hour 行由上方 hour 分支直接入桶，两条路径不重叠）。
        this.addCall(this.hourCellOf(row.day, hourOfDay(row.time)), {
          input: row.input,
          output: row.output,
          cacheRead: row.cacheRead,
          cacheWrite: row.cacheWrite,
        });
      } else {
        this.addCounter(this.cellOf(row.day, row.provider, row.model), row.turns, row.toolCalls);
        // 计数行 rebuild 同上（turns/toolCalls 平行落 dir 桶）。
        if (row.dir !== undefined) {
          this.addCounter(this.dirCellOf(row.day, row.dir), row.turns, row.toolCalls);
        }
        // 计数行 rebuild 第三面入账（同 detail 行分支）。
        this.addCounter(this.hourCellOf(row.day, hourOfDay(row.time)), row.turns, row.toolCalls);
      }
      this.pending.push({ row, persisted: persistedRows });
    }
  }

  // ---------------------------------------------------------------- 压实（日切）

  /** 存在未持久化行的日 key（升序去重）。 */
  unpersistedDays(): string[] {
    const days = new Set<string>();
    for (const p of this.pending) {
      if (!p.persisted) days.add(p.row.day);
    }
    return [...days].sort();
  }

  /** pending 全部日 key（升序去重；压实遍历用）。 */
  pendingDays(): string[] {
    const days = new Set<string>();
    for (const p of this.pending) days.add(p.row.day);
    return [...days].sort();
  }

  /** 给定日是否存在未持久化的行（压实前置条件：该日必须已全部落盘）。 */
  hasUnpersisted(day: string): boolean {
    return this.pending.some((p) => p.row.day === day && !p.persisted);
  }

  /**
   * 取走全部未持久化行（对象引用快照；await 间隙新到的行是独立对象，不受影响）。
   * 行本身保留在 pending（cells 已计入；压实前一直是今日细分查询与压实的素材）。
   */
  takeUnpersisted(): PendingEntry[] {
    return this.pending.filter((p) => !p.persisted);
  }

  /** 精确标记快照条目已持久化（append 成功后调用；只翻转快照内的对象）。 */
  markPersisted(entries: PendingEntry[]): void {
    for (const p of entries) p.persisted = true;
  }

  /**
   * 全量目录日桶快照（day 升序；报告快照与统计目录分布数据源）。
   * 委托 buildDirRows——权威口径（dirDays 单源 + 每日残差归未识别）见 buildDirRows 注释。
   */
  dirRows(): TrendDirRow[] {
    return buildDirRows(this.days, this.dirDays);
  }

  /**
   * 全量小时日桶快照（day 升序、hour 升序；报告快照数据源）。
   * 委托 buildHourRows——hourDays 单源快照、不做残差投影（口径见 buildHourRows 注释）。
   */
  hourRows(): TrendHourRow[] {
    return buildHourRows(this.hourDays);
  }

  /**
   * 堆叠柱序列（目录维度）。语义与 seriesStacked 同构：
   * 每时间桶按目录拆段；dirs 为图例并集（窗口内出现过的目录段，含未识别桶）。
   * dir 过滤可选（单目录形态——未识别桶键同为合法过滤值）。
   */
  dirStacked(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    dir: string | undefined,
    now: number,
  ): { series: TrendStackPoint[]; dirs: Array<{ dir: string }> } {
    return buildDirStackedSeries(this.dirRows(), n, gran, metric, dir, now);
  }

  /**
   * 窗口摘要（目录维度）。curRange/prevRange 语义与
   * windowSummary 完全同构：当前窗口总量/调用数/峰值桶/目录 top 段 + 上一窗口环比。
   * prevComplete 语义对齐：prev 窗口起点早于**目录面数据起点**（dirRows 最早日；
   * 残差投影后该起点等于聚合面数据起点，故与 windowSummary 同值）→ 不可比。
   */
  dirWindowSummary(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    dir: string | undefined,
    now: number,
    dirSeries?: TrendStackPoint[],
  ): TrendWindowSummary {
    return buildDirWindowSummary(this.dirRows(), n, gran, metric, dir, now, dirSeries);
  }

  /**
   * 目录窗口总量表（目录范围口径影响 + 目录分布数据源）：
   * 给定日区间内按目录聚合 calls 与 metric 总量（calls 降序）。
   */
  dirTotals(
    startDay: string,
    endDay: string,
    metric: TrendMetric = "total",
  ): Array<{ dir: string; calls: number; total: number | null }> {
    return buildDirTotals(this.dirRows(), startDay, endDay, metric);
  }

  /**
   * 给定日的目录维度折算行（读侧投影）。
   * 实现委托 {@link rollupSnapshot}——与压实路径共用同一份折算逻辑，保证「读侧
   * 看到的行」与「压实写入的行」永远同源（单一事实源，防两套实现漂移）。
   */
  takeDirUnpersisted(day: string): TrendDirRow[] {
    return this.rollupSnapshot(day).dirRows;
  }

  /**
   * 压实快照：一次遍历同时产出「该日 pending 行的身份快照」与「同源折算的
   * agg / dir 行」。
   *
   * 为什么必须同源：压实是「折算 → 落盘 → 消费」三段式，中间隔着若干 await。若消费
   * 时按日键重新查询（旧 dropPending(day) 的实现），await 期间新到达的同日行既没被
   * 折算、也没落盘，却会被连带删除（永久丢行 + 内存/磁盘漂移）。这里返回的 consumed
   * 与 aggRows/dirRows 出自同一批行，调用方持久化成功后只消费 consumed——新到达的行
   * 留待下一轮压实。
   *
   * 折算口径与读侧投影一致：dir 键缺失的行只进 agg 行（目录维度为加性可选键，
   * 缺键 = 无 dir 事实可折叠，不在折算侧补造）。cells/dirDays 不动（apply 时已累加，
   * 压实只做落盘形态转换，绝不二次累加）。
   */
  rollupSnapshot(day: string): {
    consumed: PendingEntry[];
    aggRows: TrendAggRow[];
    dirRows: TrendDirRow[];
    hourRows: TrendHourRow[];
  } {
    const consumed: PendingEntry[] = [];
    const aggByKey = new Map<string, TrendAggRow>();
    const dirByKey = new Map<string, TrendDirRow>();
    // 小时档同源折算——key 为本地时区钟点（hourOfDay 现算自行 time，与
    // apply/rebuild 同源；「落盘即定型」的生成点唯一 helper）。
    const hourByKey = new Map<number, TrendHourRow>();
    for (const p of this.pending) {
      if (p.row.day !== day) continue;
      consumed.push(p);
      const row = p.row;
      const aggKey = `${row.provider}\u0000${row.model ?? ""}`;
      let agg = aggByKey.get(aggKey);
      if (agg === undefined) {
        agg = emptyAggRow(day, row.provider, row.model);
        aggByKey.set(aggKey, agg);
      }
      let dirAgg: TrendDirRow | undefined;
      if (row.dir !== undefined) {
        dirAgg = dirByKey.get(row.dir);
        if (dirAgg === undefined) {
          dirAgg = emptyDirRow(day, row.dir);
          dirByKey.set(row.dir, dirAgg);
        }
      }
      const h = hourOfDay(row.time);
      const hourAgg = hourByKey.get(h);
      let hour: TrendHourRow;
      if (hourAgg === undefined) {
        hour = emptyHourRow(day, h);
        hourByKey.set(h, hour);
      } else {
        hour = hourAgg;
      }
      if (row.kind === "detail") {
        addDetailTo(agg, row);
        if (dirAgg !== undefined) addDetailTo(dirAgg, row);
        addDetailTo(hour, row);
      } else {
        addCounterTo(agg, row.turns, row.toolCalls);
        if (dirAgg !== undefined) addCounterTo(dirAgg, row.turns, row.toolCalls);
        addCounterTo(hour, row.turns, row.toolCalls);
      }
    }
    return {
      consumed,
      aggRows: [...aggByKey.values()],
      dirRows: [...dirByKey.values()],
      hourRows: [...hourByKey.values()],
    };
  }

  /**
   * 给定日的折算聚合行（读侧投影；纯读不消费）。
   * 实现委托 {@link rollupSnapshot}——与压实路径共用同一份折算逻辑（单一事实源）。
   */
  rollupRowsOf(day: string): TrendAggRow[] {
    return this.rollupSnapshot(day).aggRows;
  }

  /**
   * 按身份消费 pending 行（压实 IO 全部成功后调用）。
   * 只删除传入快照（{@link rollupSnapshot} 的 consumed）内的 entry——await 期间新到达
   * 的同日行不在快照内，保留到下一轮压实。空数组为 no-op，重复 entry 幂等。
   *
   * cells/dirDays 不动（压实只做落盘形态转换，绝不二次累加）。dirDays 亦
   * 不随消费联动删除——目录查询面（dirRows 纯内存快照）无分片回读，删桶 = 跨天历史
   * 柱全 null；压实事实已固化在 dir 分片 + dirDays，只随 pruneDays 收缩。
   */
  consume(entries: readonly PendingEntry[]): void {
    if (entries.length === 0) return;
    const doomed = new Set(entries);
    this.pending = this.pending.filter((p) => !doomed.has(p));
  }

  /**
   * 按日键消费 pending 行（兼容面）。
   * @deprecated 按日键删除会在压实 await 窗口内连带删除新到达的同日行（丢行），
   * 不再用于压实路径。新代码请用 {@link rollupSnapshot} + {@link consume}（按身份消费）；
   * 本方法保留仅为不破坏已发布的公开面，实现已委托为「按日取快照后按身份消费」。
   */
  dropPending(day: string, today: string): void {
    void today;
    this.consume(this.pending.filter((p) => p.row.day === day));
  }

  /**
   * 裁剪内存日桶（prune 同步收缩，长期运行不重启时 days 有界；cells 随桶整体丢弃）。
   * dirDays 联动删除（与压实消费对称，生命周期与 days 一致；
   * 独立遍历不依赖 days 键集，纯 dir 日桶（无 agg 行的防御形态）也能清）。
   */
  pruneDays(beforeDay: string): number {
    let removed = 0;
    for (const day of [...this.days.keys()]) {
      if (day < beforeDay) {
        this.days.delete(day);
        removed += 1;
      }
    }
    for (const day of [...this.dirDays.keys()]) {
      if (day < beforeDay) this.dirDays.delete(day);
    }
    // hourDays 与 days/dirDays 生命周期同步（独立遍历，防纯 hour 日桶残留）
    for (const day of [...this.hourDays.keys()]) {
      if (day < beforeDay) this.hourDays.delete(day);
    }
    return removed;
  }

  /**
   * 日切压实（一步式）：折叠为聚合行返回并从 pending 移除。
   * 仅供启动自愈等「无并发 IO 失败窗口」的同步场景使用；flush 压实路径一律走
   * rollupSnapshot + consume 两步式（IO 失败内存行保留，防丢数）。
   * 返回混存行——agg 行在前、dir 行居中、hour 行在后（writeAggDay 写入约定）。
   * today 参数保留（与调用方注入时钟同源的语义锚点；消费已不依赖日键，见 consume）。
   */
  rollupDay(day: string, today: string): Array<TrendAggRow | TrendDirRow | TrendHourRow> {
    void today;
    const { consumed, aggRows, dirRows, hourRows } = this.rollupSnapshot(day);
    this.consume(consumed);
    return [...aggRows, ...dirRows, ...hourRows];
  }

  // ---------------------------------------------------------------- 查询

  /** 全量桶快照（day 升序；路由与堆叠柱状的数据源）。 */
  buckets(): Array<{
    day: string;
    providers: Array<{ provider: string; model: string | null; cell: TrendCell }>;
  }> {
    const out: Array<{
      day: string;
      providers: Array<{ provider: string; model: string | null; cell: TrendCell }>;
    }> = [];
    for (const day of [...this.days.keys()].sort()) {
      const providers: Array<{ provider: string; model: string | null; cell: TrendCell }> = [];
      for (const [provider, models] of this.days.get(day)!) {
        for (const [model, cell] of models) {
          providers.push({ provider, model, cell });
        }
      }
      out.push({ day, providers });
    }
    return out;
  }

  /** 近 n 日序列（含今日；空日补 null——零 usage 语义，非 0）。 */
  seriesDays(
    n: number,
    now: number,
    metric: TrendMetric,
    provider?: string,
  ): Array<{ day: string; value: number | null }> {
    return lastNDayKeys(n, now).map((day) => ({
      day,
      value: dayValueOf(this.days, day, metric, provider),
    }));
  }

  /** 近 n 周序列（周一起点；key = 周首日 day key）。 */
  seriesWeeks(
    n: number,
    now: number,
    metric: TrendMetric,
    provider?: string,
  ): Array<{ day: string; value: number | null }> {
    const keys = lastNWeekKeys(n, now);
    return keys.map((day) => ({
      day,
      value: rangeValueOf(this.days, weekRange(day), metric, provider),
    }));
  }

  /** 近 n 月序列（key = YYYY-MM）。 */
  seriesMonths(
    n: number,
    now: number,
    metric: TrendMetric,
    provider?: string,
  ): Array<{ day: string; value: number | null }> {
    const keys = lastNMonthKeys(n, now);
    return keys.map((key) => ({
      day: key,
      value: rangeValueOf(this.days, monthRange(key), metric, provider),
    }));
  }

  /**
   * 堆叠柱序列（/trend 路由数据源）：每时间桶按 provider（byModel 时细到
   * provider+model）拆段；providers 为图例并集（窗口内出现过的段）。
   * 委托 buildStackedSeries（days 显式传参，查询投影纯计算）。
   */
  seriesStacked(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    provider: string | undefined,
    byModel: boolean,
    now: number,
  ): { series: TrendStackPoint[]; providers: Array<{ provider: string; model: string | null }> } {
    return buildStackedSeries(this.days, n, gran, metric, provider, byModel, now);
  }

  /**
   * 窗口摘要（当前 n 桶 + 上一同等窗口环比基准）。
   * 委托 buildWindowSummary；stackSeries 可选传入路由已算好的堆叠序列复用遍历
   * （须与 n/gran/metric/provider 同参，见 aggregator.windowSummary 契约）。
   */
  windowSummary(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    provider: string | undefined,
    now: number,
    stackSeries?: TrendStackPoint[],
  ): TrendWindowSummary {
    return buildWindowSummary(this.days, n, gran, metric, provider, now, stackSeries);
  }

  /** 统计摘要（health 观测面）。 */
  stats(): { days: number; pendingRows: number; unpersistedRows: number } {
    return {
      days: this.days.size,
      pendingRows: this.pending.length,
      unpersistedRows: this.pending.filter((p) => !p.persisted).length,
    };
  }

  // ---------------------------------------------------------------- 内部（桶构建）

  private cellOf(day: string, provider: string, model: string | null): TrendCell {
    let providers = this.days.get(day);
    if (providers === undefined) {
      providers = new Map();
      this.days.set(day, providers);
    }
    let models = providers.get(provider);
    if (models === undefined) {
      models = new Map();
      providers.set(provider, models);
    }
    let cell = models.get(model);
    if (cell === undefined) {
      cell = emptyCell();
      models.set(model, cell);
    }
    return cell;
  }

  /** dir 维度日桶定位（仿 cellOf；day → dir → cell，缺桶逐级补建）。 */
  private dirCellOf(day: string, dir: string): TrendCell {
    let dirs = this.dirDays.get(day);
    if (dirs === undefined) {
      dirs = new Map();
      this.dirDays.set(day, dirs);
    }
    let cell = dirs.get(dir);
    if (cell === undefined) {
      cell = emptyCell();
      dirs.set(dir, cell);
    }
    return cell;
  }

  /** hour 维度日桶定位（仿 cellOf/dirCellOf；day → hour(0-23) → cell，缺桶逐级补建）。 */
  private hourCellOf(day: string, hour: number): TrendCell {
    let hours = this.hourDays.get(day);
    if (hours === undefined) {
      hours = new Map();
      this.hourDays.set(day, hours);
    }
    let cell = hours.get(hour);
    if (cell === undefined) {
      cell = emptyCell();
      hours.set(hour, cell);
    }
    return cell;
  }
}

// ---------------------------------------------------------------- 纯函数 re-export（公开面兼容）

// 以下符号迁至 aggregate-rows.ts / aggregate-query.ts 后经此处
// re-export——保持 import "aggregator.ts" 的路径可达（目录化后目录外消费方走
// aggregate/interface.ts，本 re-export 为既有路径兼容面，不重复导出）。
export {
  metricValue,
  weekStartKey,
  lastNWeekKeys,
  lastNMonthKeys,
  monthRange,
  weekRange,
} from "./aggregate-query.ts";
export { mergeAggRows, mergeDirRows, mergeHourRows } from "./aggregate-rows.ts";
export type {
  TrendGranularity,
  TrendMetric,
  TrendStackPart,
  TrendStackPoint,
  TrendWindowSummary,
} from "./aggregate-query.ts";

/**
 * dsh-provider-usage/trend — TrendTracker 组合根。
 *
 * collector（事件折叠）→ aggregator（内存聚合）→ store（按天分片 JSONL）的组合：
 * - 刷盘三挂点（方案定稿）：3~5s 防抖 + `session/flush` 官方排空点 + dispose await；
 * - 启动重建：聚合分片（权威，agg+dir+hour 混存全量读回，dir/hour 行进内存
 *   目录/小时视图）＋ 当日明细分片 → 内存聚合；过去日明细分片自愈压实；
 * - 崩溃安全：压实先原子写聚合分片再删明细分片；同日并存时聚合权威（见 store）；
 * - 已知边界（文档化口径）：kill -9 丢防抖窗口数据（事件路线无重扫兜底）；
 *   统计自挂载时点起算。
 */
import { dayKey } from "../../shared/interface.ts";
import {
  TrendAggregator,
  mergeAggRows,
  mergeDirRows,
  mergeHourRows,
  type TrendGranularity,
  type TrendMetric,
  type TrendStackPoint,
  type TrendWindowSummary,
} from "./aggregator.ts";
import type { TrendCollector, TrendCollectorOptions } from "../collect/interface.ts";
import { TrendStore } from "./store.ts";
import type { TrendAggRow, TrendDirRow, TrendHourRow } from "../shared/interface.ts";
import { safeId } from "../shared/interface.ts";

export interface TrendTrackerOptions {
  /**
   * 采集器工厂（#768 B1：TrendCollector 有状态类留 collect 域，本域不直引
   * collect 门面值边；组合根注入 (opts) => new TrendCollector(opts)，纯面
   * （sumToken 等）A 波已下沉 shared，本波只做有状态注入）。
   */
  makeCollector: (opts: TrendCollectorOptions) => TrendCollector;
  /** 存储根（<historyRoot>/trend）。 */
  root: string;
  /** 聚合分片保留天数（默认 180，可配）。 */
  retentionDays?: number;
  /** 防抖毫秒（方案定稿 3~5s；默认 4s）。 */
  flushDebounceMs?: number;
  /** 注入时钟（测试用；默认 Date.now）。 */
  now?: () => number;
  /** 诊断出口（默认 console.warn）。 */
  warn?: (msg: string) => void;
  /**
   * 目录归属解析器（可选）：输入 session id，返回 cwd 原始值
   * 或 undefined（store 无该 session / header.cwd 缺失）。抛错由 collector 捕获归
   * 未识别桶；缺省 = 不接 store（纯离线/测试），目录恒归未识别桶。
   */
  resolveCwd?: (session: string) => string | undefined;
}

export class TrendTracker {
  private readonly collector: TrendCollector;
  private readonly aggregator: TrendAggregator;
  private readonly store: TrendStore;
  private readonly now: () => number;
  private readonly warn: (msg: string) => void;
  private readonly flushDebounceMs: number;
  private readonly retentionDays: number;
  private flushTimer: ReturnType<typeof setTimeout> | null = null;
  private flushChain: Promise<void> = Promise.resolve();
  private disposed = false;
  private lastFlushAt: number | null = null;

  private constructor(
    resolved: {
      makeCollector: (opts: TrendCollectorOptions) => TrendCollector;
      retentionDays: number;
      flushDebounceMs: number;
      now: () => number;
      warn: (msg: string) => void;
      resolveCwd?: (session: string) => string | undefined;
    },
    store: TrendStore,
  ) {
    this.now = resolved.now;
    this.warn = resolved.warn;
    this.flushDebounceMs = resolved.flushDebounceMs;
    this.retentionDays = resolved.retentionDays;
    this.store = store;
    this.aggregator = new TrendAggregator();
    this.collector = resolved.makeCollector({
      now: resolved.now,
      resolveCwd: resolved.resolveCwd, // 目录归属透传（collector 侧 per-session 惰性单查）
      emit: (e) => {
        this.aggregator.apply(e);
        this.markDirty();
      },
      // 归属异常（主源与 message.source 副源不一致等）经统一诊断出口告警
      onAnomaly: (msg) => resolved.warn(`归属异常：${msg}`),
    });
  }

  /** 启动：载入分片重建内存聚合 + 过去日明细分片自愈压实。 */
  static async start(opts: TrendTrackerOptions): Promise<TrendTracker> {
    // #768 B1c 运行时锁：工厂漏传在编译期外再加显式守卫（未装配占位抛错，不给空实现）。
    if (!opts.makeCollector) throw new Error("TrendTracker.start 缺少 makeCollector 工厂");
    const resolved = {
      retentionDays: opts.retentionDays ?? 180,
      flushDebounceMs: opts.flushDebounceMs ?? 4000,
      makeCollector: opts.makeCollector,
      now: opts.now ?? Date.now,
      warn: opts.warn ?? ((msg: string) => console.warn(`[dsh-provider-usage] trend: ${msg}`)),
      resolveCwd: opts.resolveCwd,
    };
    const tracker = new TrendTracker(
      resolved,
      new TrendStore({ root: opts.root, warn: resolved.warn }),
    );
    await tracker.rebuildFromDisk();
    return tracker;
  }

  /** 重启重建（崩溃安全约定：聚合分片权威；过去日明细自愈压实，见模块注释）。 */
  private async rebuildFromDisk(): Promise<void> {
    const today = dayKey(this.now());
    for (const day of await this.store.listAggDays()) {
      // 混存分片全量读回（agg+dir）——dir 行经 rebuild 的 dir 分支
      // mergeCell 进 dirDays（重启后内存目录视图恢复，分片 b 视图假设成立）；
      // agg 行照旧进 cells。dir 行不进 cells/pending（rebuild 内 continue），
      // 防双计语义与读回前一致。
      this.aggregator.rebuild(await this.store.readAggDayShard(day), false);
    }
    for (const day of await this.store.listDetailDays()) {
      const rows = await this.store.readDetailShard(day);
      if (day < today) {
        if (await this.store.hasAggShard(day)) {
          // 压实残留（崩溃于写聚合后、删明细前）：聚合权威 → 忽略明细并删除
          await this.store.deleteDetailShard(day);
          continue;
        }
        if (rows.length === 0) {
          // 白名单读（detail|counter）后为空 = 该明细分片只含非明细行（agg/dir 误落，
          // 或全为坏行）。此类分片永无压实素材，`continue` 会让它每轮重建都被重扫
          // 却永不清理——直接删除（无重建价值；坏行已由 readShard 告警留痕）。
          await this.store.deleteDetailShard(day);
          continue;
        }
        // 崩溃于压实前：明细权威 → 重建进内存后立即压实（自愈）
        this.aggregator.rebuild(rows, true);
        const aggRows = this.aggregator.rollupDay(day, today);
        await this.store.writeAggDay(day, aggRows);
        await this.store.deleteDetailShard(day);
      } else {
        // 当日明细：重建进内存（已落盘，防二次 append）
        this.aggregator.rebuild(rows, true);
      }
    }
  }

  // ---------------------------------------------------------------- 事件入口

  /**
   * session/event 入口（apply 挂接）。session 取 id 防御；异常由 collector 内部
   * try/catch 吞掉（单事件失败不连坐）。
   */
  handleEvent(session: unknown, event: Parameters<TrendCollector["handleEvent"]>[1]): void {
    const id =
      session !== null && typeof session === "object"
        ? safeId((session as { id?: unknown }).id)
        : null;
    if (id === null) return;
    this.collector.handleEvent(id, event);
  }

  /** session/disposed 入口：per-session 状态清理（缓冲 GC 三重保险之一）。 */
  handleDisposed(session: unknown): void {
    const id =
      session !== null && typeof session === "object"
        ? safeId((session as { id?: unknown }).id)
        : null;
    if (id === null) return;
    this.collector.handleDisposed(id);
  }

  // ---------------------------------------------------------------- 刷盘

  private markDirty(): void {
    if (this.disposed) return;
    if (this.flushTimer !== null) return;
    this.flushTimer = setTimeout(() => {
      this.flushTimer = null;
      void this.flushNow();
    }, this.flushDebounceMs);
    (this.flushTimer as { unref?: () => void }).unref?.();
  }

  /**
   * 排空：未落盘行 append 到日分片 → 过去日压实（先聚合分片后删明细，崩溃安全序）。
   * 并发调用经链式串行；失败不抛（下轮防抖重试），成功行才标记已持久化。
   */
  async flushNow(): Promise<void> {
    if (this.disposed) return;
    const run = this.flushChain.then(() => this.flushInner());
    this.flushChain = run.catch(() => {});
    return run;
  }

  private async flushInner(): Promise<void> {
    const today = dayKey(this.now());
    // 1. 持久化未落盘行（含时钟回拨落入过去日的行——先落明细再压实，防丢；
    //    快照精确标记：await 间隙新到的行是独立对象，不误标；
    //    按日成功集标记：部分日失败时成功日不重复 append（防崩溃重建双算））
    const dirtyDays = this.aggregator.unpersistedDays();
    if (dirtyDays.length > 0) {
      const snapshot = this.aggregator.takeUnpersisted();
      const okDays = await this.store.appendRows(snapshot.map((p) => p.row));
      if (okDays.size > 0) {
        this.aggregator.markPersisted(snapshot.filter((p) => okDays.has(p.row.day)));
      }
    }
    // 2. 过去日压实（仅该日明细已全部落盘才压，防内存压掉磁盘没落的数据；
    //    两步式安全序：先纯计算聚合行 → 既有聚合合并 → 原子写 → 删明细分片 →
    //    全部成功后才消费内存行（任一步失败内存行保留，防丢数）。
    //    逐日 try/catch：单日失败记 warn 留待下轮，保证 flushInner 永不 reject——
    //    防抖路径 void 调用不产生 unhandledRejection，session/flush 官方排空点
    //    不向宿主 checkpoint 传播插件内部错误（不连坐约定）。
    for (const day of this.aggregator.pendingDays()) {
      if (day >= today) continue;
      if (this.aggregator.hasUnpersisted(day)) continue; // 上一步失败：留到下轮
      try {
        // 折算与消费取同一份身份快照——下面三个 await 期间新到达的同日行既不入
        // 本次折算、也不被消费，留待下一轮压实（旧实现按日键删除会连带丢掉这些行）。
        const {
          consumed,
          aggRows: pendingAgg,
          dirRows: pendingDir,
          hourRows: pendingHour,
        } = this.aggregator.rollupSnapshot(day);
        // 既有聚合分片全量取回（agg+dir+hour 混存）——若仍走
        // readAggShard（只取 agg 行），整日原子重写会把分片内既有 dir/hour 行抹掉；
        // 三组必须各自与既有行合并后一起重写（迟到旧日行二次压实防丢防重——
        // 漏合并 hour 行 → 分片内既有小时数据被抹，P0）。
        const existing = await this.store.readAggDayShard(day);
        const aggRows = mergeAggRows(
          existing.filter((r): r is TrendAggRow => r.kind === "agg"),
          pendingAgg,
        );
        const dirRows = mergeDirRows(
          existing.filter((r): r is TrendDirRow => r.kind === "dir"),
          pendingDir,
        );
        const hourRows = mergeHourRows(
          existing.filter((r): r is TrendHourRow => r.kind === "hour"),
          pendingHour,
        );
        await this.store.writeAggDay(day, [...aggRows, ...dirRows, ...hourRows]); // agg 前、dir 中、hour 后（写入约定）
        // 聚合事实落盘后立即按身份消费。若把消费放在 deleteDetailShard 之后，
        // 删除失败时内存行保留，下一轮会拿「已含本轮值的聚合分片」再 merge 一次 →
        // 磁盘双算（实测 agg 20/2 vs 内存 10/1）。消费后 pending 不再含该日，下轮不再
        // 压实；残留的明细分片由重启时的「聚合权威」分支自愈删除。
        this.aggregator.consume(consumed);
        await this.store.deleteDetailShard(day);
      } catch (e: unknown) {
        this.warn(`压实失败（${day}）：${e instanceof Error ? e.message : String(e)}`);
      }
    }
    this.lastFlushAt = this.now();
  }

  /** dispose：清防抖 timer + 等待进行中的一轮收敛 + 最终排空（cordis disposer await）。 */
  async dispose(): Promise<void> {
    if (this.flushTimer !== null) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
    this.disposed = true;
    try {
      // 与进行中的 flushNow 串行（并发压实的迟写覆盖丢数窗口）
      await this.flushChain.catch(() => {});
      await this.flushInner();
    } catch (e: unknown) {
      this.warn(`dispose 刷盘失败：${e instanceof Error ? e.message : String(e)}`);
    }
  }

  /** 留存清理（挂 apply 现有 10min prune 周期）：磁盘 cutoff 前分片 + 内存日桶同步收缩。 */
  async prune(): Promise<number> {
    const cutoff = dayKey(this.now() - this.retentionDays * 86400000);
    const removed = await this.store.prune(cutoff);
    this.aggregator.pruneDays(cutoff);
    return removed;
  }

  // ---------------------------------------------------------------- 查询

  /** 日序列（近 n 日）。 */
  seriesDays(
    n: number,
    metric: TrendMetric,
    provider?: string,
  ): Array<{ day: string; value: number | null }> {
    return this.aggregator.seriesDays(n, this.now(), metric, provider);
  }

  /** 周序列（近 n 周，周一起点）。 */
  seriesWeeks(
    n: number,
    metric: TrendMetric,
    provider?: string,
  ): Array<{ day: string; value: number | null }> {
    return this.aggregator.seriesWeeks(n, this.now(), metric, provider);
  }

  /** 月序列（近 n 月）。 */
  seriesMonths(
    n: number,
    metric: TrendMetric,
    provider?: string,
  ): Array<{ day: string; value: number | null }> {
    return this.aggregator.seriesMonths(n, this.now(), metric, provider);
  }

  /** 全量桶快照（堆叠柱状/Top 适配器数据源）。 */
  buckets(): ReturnType<TrendAggregator["buckets"]> {
    return this.aggregator.buckets();
  }

  /**
   * 全量目录日桶快照（报告快照 dirRows 输入与统计目录分布数据源；
   * 今日桶经 pending 同源折算补齐，见 aggregator.dirRows）。
   */
  dirRows(): ReturnType<TrendAggregator["dirRows"]> {
    return this.aggregator.dirRows();
  }

  /** 堆叠柱序列（目录维度；/trend 路由 dir 过滤数据源）。 */
  dirStacked(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    dir?: string,
  ): { series: TrendStackPoint[]; dirs: Array<{ dir: string }> } {
    return this.aggregator.dirStacked(n, gran, metric, dir, this.now());
  }

  /** 窗口摘要（目录维度；/trend 路由 dir 过滤汇总卡数据源）。 */
  dirWindowSummary(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    dir?: string,
    dirSeries?: TrendStackPoint[],
  ): TrendWindowSummary {
    return this.aggregator.dirWindowSummary(n, gran, metric, dir, this.now(), dirSeries);
  }

  /** 目录窗口总量表（报告快照目录范围过滤数据源）。 */
  dirTotals(
    startDay: string,
    endDay: string,
    metric: TrendMetric = "total",
  ): Array<{ dir: string; calls: number; total: number | null }> {
    return this.aggregator.dirTotals(startDay, endDay, metric);
  }

  /**
   * 全量小时日桶快照（报告快照 byHour/byPeriod/peakHour/coveredDays 数据源）。
   * 内存 hourDays 单源快照（apply 平行累加 + rebuild 双分支读回，不折算 pending；
   * 无残差投影——旧分片缺 hour 行是物理缺失，报告侧 coveredDays 守卫降级）。
   */
  hourRows(): ReturnType<TrendAggregator["hourRows"]> {
    return this.aggregator.hourRows();
  }

  /** 堆叠柱序列（/trend 路由数据源；n 由粒度决定：日 30 / 周 12 / 月 12）。 */
  seriesStacked(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    provider?: string,
    byModel = false,
  ): { series: TrendStackPoint[]; providers: Array<{ provider: string; model: string | null }> } {
    return this.aggregator.seriesStacked(n, gran, metric, provider, byModel, this.now());
  }

  /**
   * 窗口摘要（趋势页汇总卡）。stackSeries 可选传入路由已算的堆叠序列复用遍历
   * （须与 n/gran/metric/provider 同参，见 aggregator.windowSummary）。
   */
  windowSummary(
    n: number,
    gran: TrendGranularity,
    metric: TrendMetric,
    provider?: string,
    stackSeries?: TrendStackPoint[],
  ): TrendWindowSummary {
    return this.aggregator.windowSummary(n, gran, metric, provider, this.now(), stackSeries);
  }

  /** 统计自挂载时点起算提示的数据源：最早有数据的本地日 key（无数据 null）。 */
  firstRecordedDay(): string | null {
    const days = this.aggregator.buckets();
    return days.length > 0 ? days[0].day : null;
  }

  /** 健康观测（/health 附带）。 */
  stats(): {
    days: number;
    pendingRows: number;
    unpersistedRows: number;
    lastFlushAt: number | null;
  } {
    return { ...this.aggregator.stats(), lastFlushAt: this.lastFlushAt };
  }
}

/**
 * dsh-provider-usage/trend — 按天分片 JSONL 存储。
 *
 * 目录（复用 HistoryStore 的「按天分片 + prune」模式，trend 以 day 为主键另建目录，
 * 不套 HistoryStore 的 provider/name 目录结构）：
 * - <root>/details/YYYY-MM-DD.jsonl  当日 per-step 明细/计数行（append-only，0600）
 * - <root>/agg/YYYY-MM-DD.jsonl      日切压实后的聚合行（整日原子重写：tmp+rename）
 *
 * 崩溃安全约定（重启重建无歧义的关键）：压实顺序 = 先原子写聚合分片、后删明细分片。
 * 同日两分片并存时 **聚合分片权威**（明细分片视为压实未完成的残留，重建时忽略并自愈删除）。
 *
 * 并发纪律：同日明细分片写入经 per-day Promise 链单飞串行（防 flush 与压实互吞）；
 * 聚合分片整日重写天然幂等（最后一写为准）。
 */
import {
  appendFile,
  mkdir,
  readFile,
  readdir,
  rename,
  rm,
  stat,
  writeFile,
} from "node:fs/promises";
import { join } from "node:path";
import {
  TREND_ROW_VERSION,
  isValidShardRow,
  type TrendAggRow,
  type TrendCounterRow,
  type TrendDetailRow,
  type TrendDirRow,
  type TrendHourRow,
} from "../shared/interface.ts";

export type TrendShardRow =
  TrendDetailRow | TrendCounterRow | TrendAggRow | TrendDirRow | TrendHourRow;

export class TrendStore {
  private readonly root: string;
  private readonly warn: (msg: string) => void;
  /** per-day append 串行链（day key → promise）。 */
  private detailChains = new Map<string, Promise<void>>();

  constructor(opts: { root: string; warn?: (msg: string) => void }) {
    this.root = opts.root;
    this.warn = opts.warn ?? ((msg) => console.warn(`[dsh-provider-usage] trend: ${msg}`));
  }

  private detailsDir(): string {
    return join(this.root, "details");
  }

  private aggDir(): string {
    return join(this.root, "agg");
  }

  private detailsFile(day: string): string {
    return join(this.detailsDir(), `${day}.jsonl`);
  }

  private aggFile(day: string): string {
    return join(this.aggDir(), `${day}.jsonl`);
  }

  // ---------------------------------------------------------------- 明细追加

  /**
   * 追加未持久化行到各自日分片（per-day 单飞串行）。
   * 返回本次调用中**写入成功的 day 集合**：调用方据此精确标记 persisted——
   * 部分日失败时成功日不重复 append（防崩溃重建双算）、失败日行保留待下轮重试。
   * 注意：okDays 只反映本次调用各日写入段的成败（排队在前链的历史失败不影响本次结果）。
   */
  async appendRows(rows: Array<TrendDetailRow | TrendCounterRow>): Promise<Set<string>> {
    const byDay = new Map<string, Array<TrendDetailRow | TrendCounterRow>>();
    for (const row of rows) {
      const list = byDay.get(row.day);
      if (list === undefined) byDay.set(row.day, [row]);
      else list.push(row);
    }
    const okDays = new Set<string>();
    for (const [day, dayRows] of byDay) {
      const done = this.detailChains.get(day) ?? Promise.resolve();
      const next = done
        .then(async () => {
          await mkdir(this.detailsDir(), { recursive: true });
          const body = dayRows.map((r) => JSON.stringify(r)).join("\n");
          await appendFile(this.detailsFile(day), `${body}\n`, { encoding: "utf8", mode: 0o600 });
          okDays.add(day);
        })
        .catch((e: unknown) => {
          this.warn(`明细分片写入失败（${day}）：${e instanceof Error ? e.message : String(e)}`);
        });
      this.detailChains.set(day, next);
      await next;
      // 链已收敛且无后续写入时清理表项（防 Map 无界增长）
      if (this.detailChains.get(day) === next) this.detailChains.delete(day);
    }
    return okDays;
  }

  // ---------------------------------------------------------------- 聚合压实

  /**
   * 整日聚合分片原子重写（tmp+rename，0600）。空行数组 = 删除该日聚合分片（防御）。
   * 这是「聚合分片权威」约定的写入侧：成功返回后该日聚合事实已完整落盘。
   * rows 为 agg+dir+hour 混存行（调用方约定 agg 在前、dir 居中、
   * hour 在后）——分片行自带 kind 判别，读侧按需过滤，互不干扰。
   */
  async writeAggDay(
    day: string,
    rows: Array<TrendAggRow | TrendDirRow | TrendHourRow>,
  ): Promise<void> {
    await mkdir(this.aggDir(), { recursive: true });
    if (rows.length === 0) {
      await rm(this.aggFile(day), { force: true });
      return;
    }
    // 写 tmp 前清理同日 rename 前崩溃残留的 tmp（文件名前缀 `${day}.jsonl.` 且
    // 后缀 `.tmp`）。尽力而为：清理失败不影响主流程（仅告警，下轮重写时再清）。
    try {
      const files = await readdir(this.aggDir());
      // 注解：rm 归约 Promise 集合（allSettled 逐个定责，全量 warn 后主写照常推进）。
      const deletePromises: Array<Promise<void>> = [];
      const targets: string[] = [];
      for (const f of files) {
        if (f.startsWith(`${day}.jsonl.`) && f.endsWith(".tmp")) {
          targets.push(f);
          deletePromises.push(rm(join(this.aggDir(), f), { force: true }));
        }
      }
      const results = await Promise.allSettled(deletePromises);
      const details: string[] = [];
      results.forEach((r, i) => {
        if (r.status === "rejected") {
          const file = targets[i];
          const raw = r.reason instanceof Error ? r.reason.message : String(r.reason);
          // 最小披露：只记 basename，不记绝对路径（rm 报错内嵌完整路径，此处回填为 basename）。
          details.push(`${file}：${raw.split(join(this.aggDir(), file)).join(file)}`);
        }
      });
      if (details.length > 0) {
        throw new Error(details.join("；"));
      }
    } catch (e: unknown) {
      this.warn(
        `聚合分片 tmp 残留清理失败（${day}）：${e instanceof Error ? e.message : String(e)}`,
      );
    }
    const tmp = `${this.aggFile(day)}.${Date.now()}.tmp`;
    const body = rows.map((r) => JSON.stringify(r)).join("\n");
    await writeFile(tmp, `${body}\n`, { encoding: "utf8", mode: 0o600 });
    await rename(tmp, this.aggFile(day));
  }

  /** 删除明细分片（压实收尾；文件不存在视为成功）。 */
  async deleteDetailShard(day: string): Promise<void> {
    await rm(this.detailsFile(day), { force: true });
  }

  // ---------------------------------------------------------------- 读取与重建

  /**
   * 读明细分片（坏行跳过并告警；文件不存在返回空）。
   * 过滤取白名单（detail|counter）而非「非 agg」黑名单：黑名单会把误落入明细目录的
   * agg 行当成 counter 重建进 cells（kind 不符时走 else 分支按 turns/toolCalls 折算，
   * 静默污染聚合面），也会把 dir 行当 counter 送进 rebuild 的 else 分支（虽经 kind
   * 判断只进 dirDays，但按 counter 语义折算会给出错误的目录面数值）。白名单同时让
   * 「只含非明细行」的分片读出空数组，由重建路径直接删除（见 TrendTracker.rebuildFromDisk）。
   */
  async readDetailShard(day: string): Promise<Array<TrendDetailRow | TrendCounterRow>> {
    return this.readShard(
      this.detailsFile(day),
      (r): r is TrendDetailRow | TrendCounterRow => r.kind === "detail" || r.kind === "counter",
    );
  }

  /**
   * 读聚合分片（只取 kind:"agg" 行；忽略混存分片内的 dir 行）。
   * src 生产路径已无调用方（flush 压实与重启重建均走 readAggDayShard 全量取回）；
   * 保留为读侧投影（filter kind:"agg"）供测试断言载体与
   * 「agg 行独立可读」的查询面，不删除。
   */
  async readAggShard(day: string): Promise<TrendAggRow[]> {
    return this.readShard(this.aggFile(day), (r): r is TrendAggRow => r.kind === "agg");
  }

  /**
   * 读聚合分片全量行（agg + dir + hour 混存）：flush 压实的「既有
   * 聚合合并」必须连 dir/hour 行一起取回重写，否则二次压实会把混存分片里的
   * dir/hour 行抹掉。重启重建也走本方法——dir/hour 行进 aggregator 对应内存桶
   * （不进 cells），分片内权威行经 rebuild 读回内存视图（白名单漏加 hour →
   * rebuild 后小时数据静默全丢，P0）。
   */
  async readAggDayShard(day: string): Promise<Array<TrendAggRow | TrendDirRow | TrendHourRow>> {
    return this.readShard(
      this.aggFile(day),
      (r): r is TrendAggRow | TrendDirRow | TrendHourRow =>
        r.kind === "agg" || r.kind === "dir" || r.kind === "hour",
    );
  }

  private async readShard<T extends TrendShardRow>(
    file: string,
    filter: (r: TrendShardRow) => r is T,
  ): Promise<T[]> {
    let raw: string;
    try {
      raw = await readFile(file, "utf8");
    } catch {
      return []; // ENOENT / 竞态删除：返回空
    }
    const out: T[] = [];
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (trimmed.length === 0) continue;
      let parsed: unknown;
      try {
        parsed = JSON.parse(trimmed);
      } catch {
        this.warn(`分片坏行跳过：${file}`);
        continue;
      }
      if (!isValidShardRow(parsed)) {
        this.warn(`分片行校验失败跳过（v=${(parsed as { v?: unknown }).v}）：${file}`);
        continue;
      }
      if (filter(parsed)) out.push(parsed);
    }
    return out;
  }

  /** 聚合分片是否存在且非空（「聚合权威」判定的读侧）。 */
  async hasAggShard(day: string): Promise<boolean> {
    try {
      const s = await stat(this.aggFile(day));
      return s.isFile() && s.size > 0;
    } catch {
      return false;
    }
  }

  /** 列出目录下全部日 key（升序；目录不存在返回空）。 */
  private async listDays(dir: string): Promise<string[]> {
    let files: string[];
    try {
      files = await readdir(dir);
    } catch {
      return [];
    }
    return files
      .filter((f) => f.endsWith(".jsonl"))
      .map((f) => f.slice(0, -".jsonl".length))
      .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d))
      .sort();
  }

  listDetailDays(): Promise<string[]> {
    return this.listDays(this.detailsDir());
  }

  listAggDays(): Promise<string[]> {
    return this.listDays(this.aggDir());
  }

  // ---------------------------------------------------------------- 留存清理

  /**
   * prune：删除 cutoff 日（不含）之前的聚合分片与明细分片（YYYY-MM-DD 字典序即时间序）。
   * 返回删除文件数。明细目录正常只含当日/未压实日，此处兜底清理残留。
   */
  async prune(beforeDay: string): Promise<number> {
    let removed = 0;
    for (const dir of [this.aggDir(), this.detailsDir()]) {
      for (const day of await this.listDays(dir)) {
        if (day < beforeDay) {
          try {
            await rm(join(dir, `${day}.jsonl`), { force: true });
            removed += 1;
          } catch (e: unknown) {
            this.warn(`留存清理失败（${day}）：${e instanceof Error ? e.message : String(e)}`);
          }
        }
      }
    }
    return removed;
  }
}

/** 行 schema 版本透出（测试/契约断言用）。 */
export { TREND_ROW_VERSION };

