  it("窗口 total（09-02..09-04）", () => {
    expect(sumTotal).toBe(38);
  });

  it("窗口 calls 计数（d1 1 次 + 当日 3 次）", () => {
    expect(sumCalls).toBe(4);
  });

  it("峰值桶 = 取值最大的日桶", () => {
    expect(sumPeakKey).toBe(DAY0);
  });

  it("top 段（byModel=false 视角）", () => {
