    writeFileSync(detFile, `${detailLine}\n`);
    writeFileSync(aggFile, `${aggLine}\n`);
    writeFileSync(usageFile, '{"time":1,"data":{}}\n');
    // mtime 一律设 90 天前构造过期形态（历史实现若按 mtime 启发判过期同样视为过期）
