// ---------------------------------------------------------------- schedule：#531 首次启用扣期预置

describe("schedule：#531 首次启用扣期预置", () => {
  type PresetOutcome = ReturnType<typeof presetLastRunForNewlyEnabled>;
  let r1: PresetOutcome;
